import fs from 'node:fs';
import path from 'node:path';
import { describe, expect, it } from 'vitest';
import {
  HSK1,
  HSK1_LEVEL,
  HSK_LEVELS,
  HSK_MAX,
  byLetter,
  lessonChars,
  lessonWords,
  levelData,
  normalizeHskChars,
  searchHsk,
  toneless,
  wordsWith,
} from './hsk.ts';
import { charFile } from '../domain/charFile.ts';

// Generated by `npm run data` (runs automatically before tests).
const DATA_DIR = path.resolve('public/hanzi');

describe('HSK 1 list', () => {
  it('matches the 2025 syllabus: 246 characters, 300 words', () => {
    expect(HSK1).toHaveLength(246);
    expect(HSK1_LEVEL.words).toHaveLength(300);
    const level = HSK_LEVELS.find((l) => l.id === '1');
    expect(level).toMatchObject({ chars: 246, words: 300 });
    expect(levelData('1')).toBe(HSK1_LEVEL);
    expect(levelData('2')).toBeUndefined();
    expect(levelData(undefined)).toBeUndefined();
  });

  it('has complete, unique entries', () => {
    for (const e of HSK1) {
      expect(e, JSON.stringify(e)).toMatchObject({
        c: expect.stringMatching(/^\p{Script=Han}$/u),
        py: expect.stringMatching(/\S/),
        en: expect.stringMatching(/\S/),
      });
    }
    const chars = HSK1.map((e) => e.c);
    expect(chars.filter((c, i) => chars.indexOf(c) !== i)).toEqual([]);
  });

  it('has a stroke data file for every character', () => {
    const missing = HSK1.filter(
      (e) => !fs.existsSync(path.join(DATA_DIR, charFile(e.c))),
    ).map((e) => e.c);
    expect(missing).toEqual([]);
  });

  it('splits into letter sections covering every entry', () => {
    const sections = byLetter(HSK1);
    expect(sections.map((s) => s.letter)).toEqual(
      [...sections.map((s) => s.letter)].sort(),
    );
    expect(sections.flatMap((s) => s.items)).toHaveLength(HSK1.length);
  });

  it('has complete, unique words', () => {
    const words = HSK1_LEVEL.words;
    for (const w of words) {
      expect(w, JSON.stringify(w)).toMatchObject({
        w: expect.stringMatching(/^\p{Script=Han}+$/u),
        py: expect.stringMatching(/\S/),
        en: expect.stringMatching(/\S/),
      });
    }
    const keys = words.map((w) => w.w);
    expect(keys.filter((w, i) => keys.indexOf(w) !== i)).toEqual([]);
  });

  it('finds the words of a character', () => {
    expect(wordsWith('爸')).toEqual(['爸爸']);
    expect(wordsWith('学')).toContain('学生');
  });
});

describe('HSK 1 lessons', () => {
  const { lessons } = HSK1_LEVEL;

  it('have ids 1..n, titles and 10–15 characters each', () => {
    expect(lessons.map((l) => l.id)).toEqual(lessons.map((_, i) => i + 1));
    for (const l of lessons) {
      expect(l.title).toMatch(/\S/);
      expect(l.chars.length, l.title).toBeGreaterThanOrEqual(10);
      expect(l.chars.length, l.title).toBeLessThanOrEqual(15);
    }
  });

  it('put every character of the level in exactly one lesson', () => {
    const all = lessons.flatMap((l) => l.chars);
    expect(all.filter((c, i) => all.indexOf(c) !== i)).toEqual([]);
    expect([...all].sort()).toEqual(HSK1.map((e) => e.c).sort());
    lessons.forEach((l, i) =>
      expect(lessonChars(HSK1_LEVEL, i).map((e) => e.c)).toEqual(l.chars),
    );
  });

  it('give every lesson words that use only characters learned so far', () => {
    const known = new Set<string>();
    lessons.forEach((l, i) => {
      l.chars.forEach((c) => known.add(c));
      const words = lessonWords(HSK1_LEVEL, i);
      expect(words.length, l.title).toBeGreaterThan(0);
      for (const w of words) {
        expect(
          [...w.w].every((c) => known.has(c)),
          w.w,
        ).toBe(true);
        expect(
          [...w.w].some((c) => l.chars.includes(c)),
          w.w,
        ).toBe(true);
      }
    });
    // Each word is practised once, except those with characters outside the list (饺子).
    const listed = new Set(HSK1.map((e) => e.c));
    const used = lessons.flatMap((_, i) => lessonWords(HSK1_LEVEL, i));
    const expected = HSK1_LEVEL.words.filter((w) =>
      [...w.w].every((c) => listed.has(c)),
    );
    expect(used).toHaveLength(expected.length);
    expect(used.map((w) => w.w)).not.toContain('饺子');
  });
});

describe('searchHsk', () => {
  it('returns everything for an empty query', () => {
    expect(searchHsk('  ')).toBe(HSK1);
  });

  it('pastes characters in typed order, skipping unknown and repeated ones', () => {
    expect(searchHsk('我爱你 爱 龘').map((e) => e.c)).toEqual([
      '我',
      '爱',
      '你',
    ]);
  });

  it('matches pinyin with or without tones', () => {
    expect(searchHsk('hao').map((e) => e.c)).toContain('好');
    expect(searchHsk('hǎo').map((e) => e.c)).toContain('好');
    expect(searchHsk('nu').map((e) => e.c)).toContain('女');
  });

  it('matches English meanings', () => {
    expect(searchHsk('good').map((e) => e.c)).toContain('好');
  });
});

describe('helpers', () => {
  it('strips tone marks', () => {
    expect(toneless('Nǚ')).toBe('nu');
  });

  it('normalizes stored character lists', () => {
    expect(normalizeHskChars(['好', '好', 'x', 1, '龘', '你'])).toEqual([
      '好',
      '你',
    ]);
    expect(normalizeHskChars('好')).toEqual([]);
    expect(normalizeHskChars(HSK1.map((e) => e.c))).toHaveLength(HSK_MAX);
  });
});
